export const snippetsFor = (projectId: string) =>
  codeSnippets.filter((s) => s.projectId === projectId)

export const snippetUrl = (s: CodeSnippet) =>
  `https://github.com/dev-shubhamroy/${s.repo}/blob/${s.sha}/${s.path}#L${s.startLine}-L${s.endLine}`
